// JEV Intelligent Model Selection helper functions
export function analyzeTaskComplexity(payload: RequestPayload): 'simple' | 'moderate' | 'complex' {
  const text = JSON.stringify(payload.messages || payload.prompt || '');
  const hasTools = Boolean(payload.tools && payload.tools.length > 0);
  const length = text.length;
  if (hasTools || length > 4000) return 'complex';
  if (length > 1000) return 'moderate';
  return 'simple';
}

export function jevScoreModel(row: ChainRow, payload: RequestPayload): number {
  const complexity = analyzeTaskComplexity(payload);
  let score = 100 - row.intelligence_rank * 5;
  if (complexity === 'complex') {
    score += (15 - row.intelligence_rank) * 3;
    if (payload.tools && row.supports_tools === 0) score -= 100;
  } else if (complexity === 'simple') {
    score += (row.speed_rank ?? 5) * 2;
  }
  if (row.rpm_limit && row.rpm_limit > 20) score += 5;
  return Math.max(0, score);
}
